#!/usr/bin/env node
// Generated by Agent Team Kit 0.7.1. Do not edit.
// Turns the role briefs into Claude Code subagents (.claude/agents/<role>.md), so one Claude Code session can
// delegate to the team without running a thread per role.
//
//   node tools/export-subagents.mjs [roles-dir] [--out .claude/agents] [--include-dormant] [--only a,b,c]
//                                   [--models deep=opus,standard=opus,routine=sonnet,light=haiku]
//
// Each subagent keeps its whole brief as its system prompt and points at docs/team/protocols.md and ownership.md.
// Re-run it after editing a brief; it overwrites only the files it generates (they carry a marker line).
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { loadBriefs, rolesDir } from './briefs.mjs';

const MARKER = '<!-- generated by agent-team-kit export-subagents; edit the brief, not this file -->';
export const DEFAULT_MODELS = { deep: 'opus', standard: 'opus', routine: 'sonnet', light: 'haiku' };

export function toSubagent(role, models = DEFAULT_MODELS) {
  const first = role.identity.split(/(?<=\.)\s/)[0];
  const description = `${role.title}: ${first} Use for work this role owns on the agent team.`.replace(/\s+/g, ' ');
  const body = role.body.replace(/^#\s+.+\n+/, '');
  return [
    '---',
    `name: ${role.slug}`,
    `description: ${JSON.stringify(description)}`,
    `model: ${models[role.tier] ?? 'inherit'}`,
    '---',
    MARKER,
    '',
    `You are the **${role.title}** on this project's agent team. Your brief follows. The shared rules are in`,
    '`docs/team/protocols.md` and the path owners in `docs/team/ownership.md`; read both before you start.',
    'When you are run as a subagent, your final message is your HANDOFF, BUG, SIGNOFF or BLOCKED, with all its fields.',
    '',
    body.trim(),
    '',
  ].join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = process.argv.slice(2);
  const opt = (name) => { const i = args.indexOf(name); return i >= 0 ? args.splice(i, 2)[1] : undefined; };
  const out = opt('--out') ?? '.claude/agents';
  const only = opt('--only')?.split(',').map((s) => s.trim());
  const models = { ...DEFAULT_MODELS };
  for (const pair of (opt('--models') ?? '').split(',').filter(Boolean)) {
    const [k, v] = pair.split('=');
    models[k.trim()] = v.trim();
  }
  const includeDormant = args.includes('--include-dormant');
  const dir = rolesDir(args.find((a) => !a.startsWith('--')));
  const roles = loadBriefs(dir).filter((r) => (only ? only.includes(r.slug) : includeDormant || r.status !== 'dormant'));
  mkdirSync(out, { recursive: true });
  let written = 0;
  for (const r of roles) {
    const file = join(out, `${r.slug}.md`);
    if (existsSync(file) && !readFileSync(file, 'utf8').includes(MARKER)) {
      console.log(`skipped ${file} (not generated by this tool)`);
      continue;
    }
    writeFileSync(file, toSubagent(r, models));
    written++;
  }
  console.log(`${written} subagents written to ${out}`);
}
